"""The CIRCT ``hw`` dialect: modules, ports, constants and structural types.

The operations here are ordinary :class:`~src.mlir.ir.Operation` subclasses
registered against the shared MLIR context, which is what lets the parser in
:mod:`src.mlir.parser` read ``inputs/alu.mlir`` and ``inputs/counter.mlir``
directly.

Every value-producing operation also implements ``evaluate(env)``, the hook the
cycle-accurate simulator in :mod:`src.circt.simulator` drives.  ``env`` maps
either SSA :class:`~src.mlir.ir.Value` objects (IR mode) or plain signal names
(behavioural mode) to integers, so the same operation classes can be used to
build a circuit by hand without going through text.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Dict, List, Optional, Sequence, Tuple, Union

from mlir.ir import (
    ArrayAttr,
    Attribute,
    Block,
    Dialect,
    FunctionType,
    IntegerAttr,
    IntegerType,
    Location,
    Operation,
    OpaqueType,
    Region,
    StringAttr,
    Trait,
    Type,
    TypeAttr,
    Value,
    get_default_context,
)

__all__ = [
    "HW_DIALECT",
    "Direction",
    "IntType",
    "ArrayType",
    "StructType",
    "InOutType",
    "Port",
    "HWOp",
    "HWModuleOp",
    "HWModuleExternOp",
    "InstanceOp",
    "OutputOp",
    "WireOp",
    "ConstantOp",
    "ArrayCreateOp",
    "ArrayGetOp",
    "StructCreateOp",
    "StructExtractOp",
    "BitcastOp",
]

HW_DIALECT = Dialect("hw", get_default_context())

#: An environment maps SSA values *or* signal names to integers.
SignalEnv = Dict[Any, int]


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------


class Direction(Enum):
    """Port direction, spelled as it appears in the textual IR."""

    INPUT = "in"
    OUTPUT = "out"
    INOUT = "inout"

    @staticmethod
    def parse(text: Union[str, "Direction"]) -> "Direction":
        if isinstance(text, Direction):
            return text
        for candidate in Direction:
            if candidate.value == text or candidate.name.lower() == str(text).lower():
                return candidate
        raise ValueError(f"unknown port direction {text!r}")


class IntType(IntegerType):
    """``iN`` as spelled by the hardware dialects (always signless)."""

    def __init__(self, width: int) -> None:
        if width <= 0:
            raise ValueError(f"hardware integer width must be positive, got {width}")
        super().__init__(width, "signless")

    def bit_count(self) -> int:
        return self.width

    def max_value(self) -> int:
        return (1 << self.width) - 1

    def mask(self) -> int:
        return (1 << self.width) - 1

    def __repr__(self) -> str:
        return f"i{self.width}"


class ArrayType(Type):
    """``!hw.array<Nxi8>``."""

    def __init__(self, element_type: Type, size: int) -> None:
        if size <= 0:
            raise ValueError(f"array size must be positive, got {size}")
        self.element_type = element_type
        self.size = int(size)

    def __str__(self) -> str:
        return f"!hw.array<{self.size}x{self.element_type}>"

    def __repr__(self) -> str:
        return str(self)

    def bit_count(self) -> int:
        return self.size * bit_width_of(self.element_type)

    def element_at(self, index: int) -> Type:
        if index < 0 or index >= self.size:
            raise IndexError(f"array index {index} out of range for size {self.size}")
        return self.element_type


class StructType(Type):
    """``!hw.struct<name: type, ...>``."""

    def __init__(self, fields: Optional[Sequence[Tuple[str, Type]]] = None) -> None:
        self.fields: List[Tuple[str, Type]] = list(fields or ())

    def __str__(self) -> str:
        inner = ", ".join(f"{name}: {ftype}" for name, ftype in self.fields)
        return f"!hw.struct<{inner}>"

    def __repr__(self) -> str:
        return str(self)

    def bit_count(self) -> int:
        return sum(bit_width_of(ftype) for _, ftype in self.fields)

    def get_field_type(self, name: str) -> Optional[Type]:
        for field_name, ftype in self.fields:
            if field_name == name:
                return ftype
        return None

    def field_names(self) -> List[str]:
        return [name for name, _ in self.fields]


class InOutType(Type):
    """``!hw.inout<i8>``."""

    def __init__(self, inner_type: Type) -> None:
        self.inner_type = inner_type

    def __str__(self) -> str:
        return f"!hw.inout<{self.inner_type}>"

    def __repr__(self) -> str:
        return str(self)

    def bit_count(self) -> int:
        return bit_width_of(self.inner_type)


#: Opaque dialect types that are physically one wire wide.
_SINGLE_BIT_OPAQUE_MNEMONICS = frozenset({"clock", "reset", "asyncreset"})


def bit_width_of(type: Optional[Type]) -> int:
    """Best-effort bit width for any hardware type."""
    if type is None:
        return 0
    for attribute in ("bit_count",):
        method = getattr(type, attribute, None)
        if callable(method):
            return int(method())
    width = type.bitwidth()
    if width:
        return int(width)
    # ``!seq.clock`` and friends arrive from the parser as a generic
    # ``OpaqueType`` with no width; the dialect knows they are single wires.
    if isinstance(type, OpaqueType) and type.mnemonic in _SINGLE_BIT_OPAQUE_MNEMONICS:
        return 1
    return 0


HW_DIALECT.register_type_parser("array", lambda body: OpaqueType("hw", "array", body))
HW_DIALECT.register_type_parser("struct", lambda body: OpaqueType("hw", "struct", body))

