class ConstantOp(HWOp):
    """``hw.constant 5 : i4``."""

    OPERATION_NAME = "hw.constant"
    TRAITS = (Trait.PURE, Trait.CONSTANT_LIKE)

    def __init__(
        self,
        value: Optional[int] = None,
        width: int = 0,
        result_name: str = "",
        result_types: Optional[Sequence[Type]] = None,
        attributes: Optional[Dict[str, Attribute]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = dict(attributes or {})
        types = list(result_types or ())
        if not types:
            types = [IntType(width if width > 0 else 32)]
        if value is not None:
            attrs.setdefault("value", IntegerAttr(int(value), types[0]))
        super().__init__(
            result_types=types,
            attributes=attrs,
            width=width,
            result_name=result_name,
            location=location,
        )

    @property
    def value(self) -> int:
        attr = self.attributes.get("value")
        if attr is None:
            return 0
        raw = attr.value
        return int(raw) if isinstance(raw, (int, float)) else 0

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        return self.truncate(self.value)

    def fold(self) -> Optional[List[Any]]:
        return [self.evaluate()]

    def is_zero(self) -> bool:
        return self.evaluate() == 0

    def is_all_ones(self) -> bool:
        return self.evaluate() == self.mask()


class OutputOp(HWOp):
    """``hw.output %a, %b : i4, i4`` - the module terminator."""

    OPERATION_NAME = "hw.output"
    TRAITS = (Trait.TERMINATOR, Trait.PURE)

    def __init__(
        self,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        location: Optional[Location] = None,
    ) -> None:
        super().__init__(operands=operands, location=location)

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    def operand_count(self) -> int:
        return self.num_operands

    def evaluate(self, env: Optional[SignalEnv] = None) -> List[int]:
        return self.read_operands(env or {})

    def fold(self) -> Optional[List[Any]]:
        return None


class WireOp(HWOp):
    """``hw.wire %value : i4`` - a named, assignable signal."""

    OPERATION_NAME = "hw.wire"
    TRAITS = (Trait.PURE,)

    def __init__(
        self,
        name: Optional[str] = None,
        wire_type: Optional[Type] = None,
        value: Optional[Union[Value, str, int]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        location: Optional[Location] = None,
        result_types: Optional[Sequence[Type]] = None,
    ) -> None:
        ops: List[Union[Value, str]] = list(operands or ())
        self._literal: Optional[int] = None
        if isinstance(value, (Value, str)):
            ops.append(value)
        elif isinstance(value, int):
            self._literal = value
        attrs: Dict[str, Attribute] = {}
        if name:
            attrs["name"] = StringAttr(name)
        types = list(result_types or ())
        if not types and wire_type is not None:
            types = [wire_type]
        super().__init__(
            operands=ops,
            result_types=types,
            attributes=attrs,
            name=self.OPERATION_NAME,
            location=location,
        )
        self.wire_name = name or ""

    def bit_width(self) -> int:
        return self.width

    def assign(self, value: int) -> None:
        self._literal = int(value)

    def evaluate(self, env: Optional[SignalEnv] = None) -> int:
        if self.num_operands:
            return self.truncate(self.read_operand(env or {}, 0))
        return self.truncate(self._literal or 0)


class InstanceOp(HWOp):
    """``hw.instance "name" @Module(a: %x: i4) -> (r: i4)``."""

    OPERATION_NAME = "hw.instance"

    def __init__(
        self,
        instance_name: Optional[str] = None,
        module_name: Optional[str] = None,
        inputs: Optional[Dict[str, Any]] = None,
        outputs: Optional[Sequence[str]] = None,
        parameters: Optional[Dict[str, Any]] = None,
        operands: Optional[Sequence[Union[Value, str]]] = None,
        result_types: Optional[Sequence[Type]] = None,
        location: Optional[Location] = None,
    ) -> None:
        attrs: Dict[str, Attribute] = {}
        if instance_name:
            attrs["instance_name"] = StringAttr(instance_name)
        if module_name:
            attrs["module_name"] = StringAttr(module_name)
        super().__init__(
            operands=operands,
            result_types=result_types,
            attributes=attrs,
            location=location,
        )
        self.instance_name = instance_name or ""
        self.module_name = module_name or ""
        self.inputs: Dict[str, Any] = dict(inputs or {})
        self.output_names: List[str] = list(outputs or ())
        self.parameters: Dict[str, Any] = dict(parameters or {})

    @classmethod
    def default_num_results(cls) -> int:
        return 0

    def get_input(self, port_name: str) -> Any:
        return self.inputs.get(port_name)

    def set_input(self, port_name: str, value: Any) -> None:
        self.inputs[port_name] = value

    def get_output_names(self) -> List[str]:
        return list(self.output_names)

    def __repr__(self) -> str:
        return f"InstanceOp({self.instance_name} : {self.module_name})"


